function Planets() {
  const planets = ["Mercury","Venus","Earth","Mars","Jupiter","Saturn","Uranus","Neptune"]
  return (
    <div className=' text-white  '>
        <Section1/>
        {planets.map()}
        {/* <Mercury id={"Mercury"}/> */}
        {/* <Footer/> */}
    </div>
  )
}

export default Planets
